```python
class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if len(self.items) == 0:
            raise IndexError("Stack is empty")
        return self.items.pop()

class Queue:
    def __init__(self):
        self.stack1 = Stack()
        self.stack2 = Stack()

    def enqueue(self, item):
        self.stack1.push(item)

    def dequeue(self):
        if len(self.stack1) == 0:
            raise IndexError("Queue is empty")
        return self.stack2.pop()

# 示例
queue = Queue()
queue.enqueue(1)
queue.enqueue(2)
queue.enqueue(3)
print(queue.dequeue())  # 输出 3
print(queue.dequeue())  # 输出 2
print(queue.dequeue())  # 输出 1
```
在这个实现中，`Queue` 类有两个独立的栈对象 `stack1` 和 `stack2`。`enqueue` 方法向 `stack1` 推入元素，`dequeue` 方法从 `stack2` 中取出元素并返回。
